INSERT INTO reviews (review_id, user_id, location_id, review_title, rating, review_comment, visit_date, like_count, is_deleted, created_at, updated_at) VALUES (1, 11, '6', '다시 오고 싶은 장소', 1.0, '음식이 정말 맛있고 서비스도 친절했어요. 강력 추천합니다!', '2026-01-16', 110, 0, '2025-08-18 00:54:29', '2026-03-13 00:54:29');
INSERT INTO reviews (review_id, user_id, location_id, review_title, rating, review_comment, visit_date, like_count, is_deleted, created_at, updated_at) VALUES (2, 10, '6', '친구와 함께 방문했어요', 1.5, '역사적인 의미도 있고 볼거리도 많아서 좋았어요. 아이들 교육에도 좋을 것 같아요.', '2025-12-21', 36, 0, '2025-06-29 00:54:29', '2026-03-20 00:54:29');
INSERT INTO reviews (review_id, user_id, location_id, review_title, rating, review_comment, visit_date, like_count, is_deleted, created_at, updated_at) VALUES (3, 15, '5', '가족 여행 추천 스팟', 2.0, '카페 분위기가 너무 좋고 음료도 맛있었어요. 인스타 감성 맛집!', '2026-01-11', 0, 0, '2025-11-25 00:54:29', '2026-03-08 00:54:29');
INSERT INTO reviews (review_id, user_id, location_id, review_title, rating, review_comment, visit_date, like_count, is_deleted, created_at, updated_at) VALUES (4, 14, '6', '혼자 여행하기 딱 좋아요', 3.5, '자연 속에서 힐링할 수 있는 완벽한 장소입니다. 트레킹 코스도 잘 되어 있어요.', '2025-11-22', 66, 0, '2025-11-10 00:54:29', '2026-02-10 00:54:29');
INSERT INTO reviews (review_id, user_id, location_id, review_title, rating, review_comment, visit_date, like_count, is_deleted, created_at, updated_at) VALUES (5, 10, '15', '사진 찍기 너무 좋은 곳', 1.0, '쇼핑하기 정말 좋은 곳이에요. 다양한 브랜드와 맛집이 모여 있어요.', '2026-01-04', 106, 0, '2025-07-20 00:54:29', '2026-02-19 00:54:29');
